 "An intro video": "Film powitalny",
 "An invite is already an approval, so this only applies to anyone who asks without one.": "Zaproszenie jest już zgodą, więc dotyczy to tylko próśb bez zaproszenia.",
 "An invite lasts 1 to 365 days.": "Zaproszenie jest ważne od 1 do 365 dni.",
 "An invite link is the only way in.": "Wejść można tylko przez link z zaproszeniem.",
 "An order": "Zamówienie",
