 "An unticked “Email me with news and offers” box under the email. Only buyers who tick it get your campaigns.": "Niezaznaczone pole „Wysyłaj mi nowości i oferty” pod e-mailem. Kampanie dostają tylko ci, którzy je zaznaczą.",
