 "At": "O",
 "At a glance": "W skrócie",
 "At checkout": "Przy płatności",
 "At checkout Storelib adds the tax your settings above call for, shows it to the buyer, puts it on the receipt and keeps the record here. Nothing has to be set up before you can sell.": "Przy płatności Storelib dolicza podatek wynikający z Twoich ustawień powyżej, pokazuje go kupującemu, umieszcza na paragonie i zapisuje tutaj. Nie musisz niczego konfigurować, zanim zaczniesz sprzedawać.",
 "At checkout Storelib adds the tax your settings below call for, shows it to the buyer, puts it on the receipt and keeps the record here. Nothing has to be set up before you can sell.": "Przy płatności Storelib dolicza podatek wynikający z Twoich ustawień poniżej, pokazuje go kupującemu, umieszcza na paragonie i zapisuje tutaj. Nie musisz niczego konfigurować, zanim zaczniesz sprzedawać.",
 "At checkout Storelib looks at where the buyer is and adds that region's rate. Buyers anywhere else pay no tax.": "W kasie Storelib sprawdza, gdzie jest kupujący, i dolicza stawkę regionu. Kupujący spoza regionów nie płacą podatku.",
 "At checkout the buyer types their address. Storelib finds the zone it falls in and shows that zone's rates. An address in no zone cannot check out, so add every country you ship to.": "W kasie kupujący wpisuje adres. Storelib znajduje strefę i pokazuje jej stawki. Adres poza strefami nie przejdzie do płatności, więc dodaj każdy kraj, do którego wysyłasz.",
 "At least 7 days. A card is taken at sign up and charged when the trial ends, unless they cancel.": "Co najmniej 7 dni. Karta jest podawana przy zapisie i obciążana po zakończeniu okresu próbnego, chyba że ktoś zrezygnuje.",
 "At most {amount} can go back.": "Można zwrócić maksymalnie {amount}.",
 "At most {value}.": "Najwyżej {value}.",
 "At or below it is low, for every product without its own line (set in the product's Inventory card).": "Na tym poziomie lub niżej stan jest niski, dla każdego produktu bez własnego progu (ustawianego w karcie Magazyn produktu).",
 "At the check": "Na etapie sprawdzenia",
 "At the end of the period": "Na koniec okresu",
 "At the top left of your page. Visitors copy the link or send it on.": "W lewym górnym rogu strony. Odwiedzający kopiują link lub go wysyłają.",
