 "Changelog": "Nowości",
 "Changes are saved as you make them and reach your checkout within a few seconds.": "Zmiany zapisują się na bieżąco i trafiają do kasy w kilka sekund.",
 "Changes one of Storelib's sections in a way it can't use": "Zmienia sekcję Storelib w sposób, którego nie da się użyć",
 "Changes one of {oneOfOurs} sections in a way it can't use": "Zmienia jedną z sekcji {oneOfOurs} w sposób, którego nie może użyć",
 "Changes reach your live checkout within a few seconds. Nothing here touches orders already placed.": "Zmiany trafiają do kasy w kilka sekund. Nic tutaj nie wpływa na złożone zamówienia.",
 "Changes saved": "Zapisano zmiany",
