 "Changes to your account and its email address.": "Zmiany konta i jego adresu e-mail.",
 "Changes to your store, checkout, taxes, shipping and integrations show up here.": "Zmiany sklepu, kasy, podatków, wysyłki i integracji pojawią się tutaj.",
 "Changing it signs you out on your other devices.": "Zmiana wyloguje Cię na innych urządzeniach.",
 "Changing the currency asks what happens to your prices: keep the numbers (100 EUR becomes 100 USD) or convert them at the day's exchange rate. Orders already placed keep their own currency.": "Przy zmianie waluty pytamy, co zrobić z cenami: zachować liczby (100 EUR zmienia się na 100 USD) albo przeliczyć je po kursie z danego dnia. Złożone już zamówienia zachowują swoją walutę.",
 "Changing the words needs a database update (SQL part 129). The preview still works.": "Zmiana treści wymaga aktualizacji bazy danych (SQL część 129). Podgląd nadal działa.",
 "Channels you create are for keeping track, like a market stall or a wholesale list. Storelib doesn't show anything there.": "Utworzone kanały służą do śledzenia, np. stoisko na targu lub lista hurtowa. Storelib nic w nich nie pokazuje.",
