 "Checkout": "Płatność",
 "Checkout always charges your store's own currency and says so next to the total, so a converted price is shown as an estimate.": "Kasa zawsze pobiera płatność w walucie Twojego sklepu i mówi o tym obok sumy, więc przeliczona cena jest szacunkowa.",
 "Checkout canceled. Nothing changed.": "Płatność anulowana. Nic się nie zmieniło.",
 "Checkout charges the visitor's currency, the amounts they saw. A currency Storelib can't charge yet is shown for reference, and checkout says it charges yours.": "Kasa pobiera opłatę w walucie odwiedzającego, w kwotach, które widział. Waluta, której Storelib jeszcze nie obsługuje, jest pokazana orientacyjnie, a kasa informuje, że pobiera w Twojej.",
 "Checkout charges what your store's prices are in, and says so next to the total, so a converted price is always shown as an estimate.": "Kasa pobiera opłatę w walucie cen sklepu i informuje o tym przy sumie, więc przeliczona cena jest zawsze szacunkiem.",
 "Checkout conversion": "Konwersja płatności",
 "Checkout for the product they left": "Kasa dla porzuconego produktu",
 "Checkout has no way to get an order to the buyer, so nobody can buy.": "Kasa nie ma sposobu dostarczenia zamówienia, więc nikt nie może kupić.",
 "Checkout is closed until payments are set up again, so buyers cannot pay you in the meantime.": "Płatności są wstrzymane do ponownej konfiguracji, więc w tym czasie kupujący nie mogą Ci zapłacić.",
 "Checkout is the page where a buyer types their details and pays. These settings decide what it asks for.": "Kasa to strona, na której kupujący wpisuje dane i płaci. Te ustawienia decydują, o co pyta.",
