 "Checkout settings": "Ustawienia kasy",
 "Checkout settings need their database update (SQL part 109). Until it runs, checkout works as it always has and changes here are not kept.": "Ustawienia kasy wymagają aktualizacji bazy danych (część SQL 109). Do tego czasu kasa działa jak zawsze, a zmiany tutaj nie są zapisywane.",
 "Checkout text": "Teksty kasy",
 "Checkout text needs its database update (SQL part 212). Until it runs, checkout shows Storelib's words and changes here are not kept.": "Teksty kasy wymagają aktualizacji bazy danych (część SQL 212). Do tego czasu kasa pokazuje teksty Storelib, a zmiany tutaj nie są zapisywane.",
