 "It starts as a draft. Only you and your team see it until you publish, and the Overview lists what to do first.": "Zaczyna jako szkic. Do publikacji widzisz ją tylko ty i twój zespół, a Przegląd pokazuje, od czego zacząć.",
 "Step {n} of {total}": "Krok {n} z {total}",
 "That did not go through. Nothing changed. Try again.": "Nie udało się. Nic się nie zmieniło. Spróbuj ponownie.",
 "The community stays": "Społeczność zostaje",
 "Memberships ended with refunds. It is deleted once every refund has gone through.": "Członkostwa zakończono ze zwrotem pieniędzy. Zostanie usunięta, gdy wszystkie zwroty dojdą do skutku.",
 "Memberships stopped renewing and nobody new can join. Members can read it until then. {stopped} of {total} memberships stopped.": "Członkostwa nie odnawiają się i nikt nowy nie może dołączyć. Do tego czasu członkowie mogą ją czytać. Zatrzymano {stopped} z {total} członkostw.",
 "Keep the community": "Zachowaj społeczność",
 "{n, plural, one {# membership has} other {# memberships have}} not gone through with Stripe yet. Storelib tries again every few minutes.": "{n, plural, one {# członkostwo nie zostało jeszcze przetworzone} few {# członkostwa nie zostały jeszcze przetworzone} many {# członkostw nie zostało jeszcze przetworzonych} other {# członkostwa nie zostało jeszcze przetworzone}} w Stripe. Storelib ponawia próbę co kilka minut.",
 "Keep this community?": "Zachować tę społeczność?",
 "Memberships renew again as before and the community comes back the way it was. Members are told by email.": "Członkostwa znów się odnawiają, a społeczność wraca do poprzedniego stanu. Członkowie dostaną e-mail.",
 "{n, plural, one {# member pays} other {# members pay}} for it. Their memberships are cancelled first, then it is deleted.": "{n, plural, one {# członek płaci} few {# członkowie płacą} many {# członków płaci} other {# członka płaci}} za nią. Najpierw anulujemy ich członkostwa, potem ją usuwamy.",
 "It disappears for everyone. Orders and payments are kept.": "Znika dla wszystkich. Zamówienia i płatności zostają.",
 "End memberships and delete": "Zakończ członkostwa i usuń",
 "{n, plural, one {# member pays} other {# members pay}} for this community. Nobody new can join from the moment you confirm, and every member gets an email.": "{n, plural, one {# członek płaci} few {# członkowie płacą} many {# członków płaci} other {# członka płaci}} za tę społeczność. Od chwili potwierdzenia nikt nowy nie dołączy, a każdy członek dostanie e-mail.",
 "When memberships end": "Kiedy kończą się członkostwa",
 "When their paid time runs out": "Gdy skończy się opłacony okres",
 "Renewals stop now and nobody is charged again. Members keep access until {date}, then the community is deleted. You can undo this until then.": "Odnowienia zatrzymują się teraz i nikt nie zostanie ponownie obciążony. Członkowie mają dostęp do {date}, potem społeczność zostanie usunięta. Do tego czasu możesz to cofnąć.",
 "Now, with refunds": "Teraz, ze zwrotem pieniędzy",
 "Memberships end today. Each member gets back what they paid for the time left, about {amount} in all. This cannot be undone.": "Członkostwa kończą się dziś. Każdy członek odzyska to, co zapłacił za pozostały czas, łącznie około {amount}. Tego nie da się cofnąć.",
 "skipped": "pominięto",
 "I have it": "Już mam",
