 "Watch": "Obejrzyj",
 "Glad you are here. Start by saying hello in Introductions: who you are and what you want to get out of {name}. Then have a look around and ask anything.": "Miło, że jesteś. Zacznij od przywitania się w Przedstawieniach: kim jesteś i czego oczekujesz od {name}. Potem rozejrzyj się i pytaj o wszystko.",
 "That address is kept for Storelib. Try another.": "Ten adres jest zarezerwowany dla Storelib. Wybierz inny.",
 "Name the first space.": "Nazwij pierwszą przestrzeń.",
