 "How people joined in this period, why members left, and who stayed.": "Jak ludzie dołączali w tym okresie, dlaczego członkowie odeszli i kto został.",
 "Members who opened the community or did something in it.": "Członkowie, którzy otworzyli społeczność lub coś w niej zrobili.",
 "The posts that drew the most likes and comments, and the members behind them.": "Posty z największą liczbą polubień i komentarzy oraz członkowie, którzy za nimi stoją.",
 "Where this period's money came from, and the members paying for the community.": "Skąd pochodziły pieniądze w tym okresie i którzy członkowie płacą za społeczność.",
