 "Chat settings did not load. Refresh the page.": "Ustawienia czatu się nie wczytały. Odśwież stronę.",
 "They can chat again": "Ta osoba znów może pisać na czacie",
 "Kept out of chat": "Wykluczeni z czatu",
 "Muted in chat": "Wyciszono na czacie",
 "Chat settings need the database update for chat (run-now part 270). Until it runs, chat works as before, without groups, rules or slow mode per channel.": "Ustawienia czatu wymagają aktualizacji bazy danych dla czatu (run-now część 270). Do tego czasu czat działa jak dotąd, bez grup, zasad i trybu powolnego dla kanałów.",
 "Chat channels and messages between members. Turned off, nothing in them is deleted.": "Kanały czatu i wiadomości między członkami. Po wyłączeniu nic nie jest usuwane.",
 "Members see the chat channels and the Messages button.": "Członkowie widzą kanały czatu i przycisk Wiadomości.",
 "Channels": "Kanały",
 "Edit in Spaces": "Edytuj w Przestrzeniach",
 "Slow mode: {time}": "Tryb powolny: {time}",
 "No slow mode": "Bez trybu powolnego",
 "No chat channels yet. Add a space of the chat kind in Spaces.": "Nie ma jeszcze kanałów czatu. Dodaj przestrzeń typu czat w Przestrzeniach.",
 "Who can post in each channel is set on the channel in Spaces. The team is never slowed.": "Kto może pisać w kanale, ustawiasz przy kanale w Przestrzeniach. Zespołu tryb powolny nie dotyczy.",
 "Messages between members": "Wiadomości między członkami",
 "Members can also choose who may message them, and block anyone.": "Członkowie mogą też wybrać, kto może do nich pisać, i zablokować każdego.",
 "Who can send messages": "Kto może wysyłać wiadomości",
 "The team only": "Tylko zespół",
 "Members can message the owner, admins and moderators. The team can message anyone.": "Członkowie mogą pisać do właściciela, adminów i moderatorów. Zespół może pisać do każdego.",
 "Nobody can start or answer a message.": "Nikt nie może zacząć ani odpowiedzieć na wiadomość.",
 "Any member can message any other member.": "Każdy członek może pisać do każdego innego.",
 "Who can start a group": "Kto może założyć grupę",
 "Pictures and phones": "Zdjęcia i telefony",
 "Pictures and files in chat": "Zdjęcia i pliki na czacie",
 "Up to 10 in a message, 50 MB each. The team can always send them.": "Do 10 w wiadomości, po 50 MB. Zespół zawsze może je wysyłać.",
 "Show the words on phones": "Pokazuj treść na telefonach",
 "Turned off, a notification says New message and who sent it.": "Po wyłączeniu powiadomienie pokazuje Nowa wiadomość i nadawcę.",
 "Chat rules": "Zasady czatu",
 "Each member reads and accepts these once, before their first message. When you change them, everyone is asked again.": "Każdy członek czyta je i akceptuje raz, przed pierwszą wiadomością. Gdy je zmienisz, wszyscy zostaną zapytani ponownie.",
 "Be kind. No selling in chat. Keep it on topic.": "Bądź miły. Bez sprzedaży na czacie. Trzymaj się tematu.",
 "Version {n}. Blocked words from Rules and policies apply in chat too.": "Wersja {n}. Zablokowane słowa z Zasad i polityk obowiązują też na czacie.",
 "Blocked words from Rules and policies apply in chat too.": "Zablokowane słowa z Zasad i polityk obowiązują też na czacie.",
 "A member muted or banned here can still read the community and its chat. Reports of messages are in Moderation.": "Członek wyciszony lub wykluczony tutaj nadal może czytać społeczność i jej czat. Zgłoszenia wiadomości są w Moderacji.",
 "Banned from chat": "Zablokowany na czacie",
 "Nobody is kept out of chat.": "Nikt nie jest wykluczony z czatu.",
