 "Change automated message": "Zmień wiadomość automatyczną",
 "Channel": "Kanał",
 "Chat is off in this community, so nothing is sent until it is on again.": "Czat jest wyłączony w tej społeczności, więc nic nie zostanie wysłane, dopóki nie zostanie włączony.",
 "Chat tab": "Karta Czat",
 "Days": "Dni",
 "Delete this automated message?": "Usunąć tę wiadomość automatyczną?",
 "Filled in for each member:": "Uzupełniane dla każdego członka:",
 "For memberships members pay for here.": "Dla członkostw, za które członkowie płacą tutaj.",
 "From a level": "Od poziomu",
 "Hi {first_name}, welcome to {community}! Say hello in the chat and tell us what brought you here.": "Cześć {first_name}, witaj w {community}! Przywitaj się na czacie i napisz, co cię tu sprowadziło.",
 "How Ana reads it": "Jak przeczyta to Ana",
 "It goes out in small batches, never twice to the same member.": "Wychodzi małymi partiami, nigdy dwa razy do tego samego członka.",
 "Members after some days here": "Członkowie po kilku dniach tutaj",
 "Members can message the team": "Członkowie mogą pisać do zespołu",
 "Members from a level": "Członkowie od poziomu",
 "Members of a tier": "Członkowie planu",
 "Members start conversations after {n} days here. Before that they can answer one and message the team.": "Członkowie zaczynają rozmowy po {n} dniach tutaj. Wcześniej mogą odpowiedzieć na rozmowę i pisać do zespołu.",
 "Members start conversations after {n} days here. Before that they can only answer one.": "Członkowie zaczynają rozmowy po {n} dniach tutaj. Wcześniej mogą tylko odpowiedzieć na rozmowę.",
 "Members start conversations from level {n}. Before that they can answer one and message the team.": "Członkowie zaczynają rozmowy od poziomu {n}. Wcześniej mogą odpowiedzieć na rozmowę i pisać do zespołu.",
 "Members start conversations from level {n}. Before that they can only answer one.": "Członkowie zaczynają rozmowy od poziomu {n}. Wcześniej mogą tylko odpowiedzieć na rozmowę.",
 "Members who joined before you turn this on are not sent it.": "Członkowie, którzy dołączyli przed włączeniem, jej nie dostaną.",
 "Members who joined lately": "Członkowie, którzy niedawno dołączyli",
