 "Only the team sees it.": "Widzi ją tylko zespół.",
 "Only the team starts conversations. Members can answer them.": "Tylko zespół zaczyna rozmowy. Członkowie mogą na nie odpowiadać.",
 "Opens from the Chat tab": "Otwiera się z karty Czat",
 "Pause": "Wstrzymaj",
