 "Sending now": "Wysyłanie trwa",
 "Sends {when}": "Wysyłka {when}",
 "Sent by someone on the team into each member's messages, or into a channel. Each member gets each one once.": "Wysyła je ktoś z zespołu do wiadomości każdego członka albo na kanał. Każdy członek dostaje każdą tylko raz.",
 "Some days after someone joins": "Kilka dni po dołączeniu",
 "The Chat tab, levels for messages and pinned messages need the database update for chat (run-now part 272).": "Karta Czat, poziomy dla wiadomości i przypięte wiadomości wymagają aktualizacji bazy danych dla czatu (run-now część 272).",
