 "Not counted for this period.": "Nie liczono w tym okresie.",
 "How each visitor arrived, once a day: a search engine, a social app, Explore, another site, or typed in directly. Then the site that sent them, their country and their device.": "Skąd przyszedł każdy odwiedzający, raz dziennie: z wyszukiwarki, aplikacji społecznościowej, Odkrywaj, innej strony lub po wpisaniu adresu. Potem strona, która go przysłała, jego kraj i urządzenie.",
 "No invite link was used in this period.": "W tym okresie nie użyto żadnego linku z zaproszeniem.",
 "How the people who joined in this period got in: for free, by paying, by an invite, or added by you or your team. Invites: the links that brought them.": "Jak dołączyły osoby z tego okresu: za darmo, płacąc, przez zaproszenie albo dodane przez ciebie lub twój zespół. Zaproszenia: linki, które je przyprowadziły.",
 "Where this period's money came from, less refunds: memberships and purchases, programs, event tickets. By plan: each plan by the name it is sold under, with the members paying for it at the end of the period.": "Skąd przyszły pieniądze w tym okresie, po zwrotach: członkostwa i zakupy, programy, bilety na wydarzenia. Według planu: każdy plan pod nazwą, pod którą jest sprzedawany, z członkami płacącymi za niego na koniec okresu.",
 "By plan": "Według planu",
 "Revenue by plan": "Przychód według planu",
 "No plan sold in this period.": "W tym okresie nie sprzedano żadnego planu.",
 "{stayed} of {joined}": "{stayed} z {joined}",
 "{active} of {joined}": "{active} z {joined}",
 "Retention": "Utrzymanie",
 "The members who joined in each month. Still members: how many have not left. Still active: how many were here in the last 30 days.": "Członkowie, którzy dołączyli w każdym miesiącu. Nadal członkami: ilu nie odeszło. Nadal aktywni: ilu było tu w ostatnich 30 dniach.",
 "Still members": "Nadal członkami",
 "Nobody joined in these months.": "W tych miesiącach nikt nie dołączył.",
 "Still active": "Nadal aktywni",
 "Members still active": "Członkowie nadal aktywni",
 "Members who opened the community or did something in it. New: they joined in this period. Lately: who was here in the last day, week and month.": "Członkowie, którzy otworzyli społeczność albo coś w niej zrobili. Nowi: dołączyli w tym okresie. Ostatnio: kto był tu w ostatnim dniu, tygodniu i miesiącu.",
 "The reason each member picked when they left, and each paid member when they cancelled.": "Powód, który wybrał każdy członek przy odejściu, i każdy płacący członek przy anulowaniu.",
 "The posts of this period that drew the most likes and comments, and the spaces with the most posts and comments.": "Posty z tego okresu z największą liczbą polubień i komentarzy oraz przestrzenie z największą liczbą postów i komentarzy.",
 "Top members": "Najlepsi członkowie",
 "The members who posted and commented the most in this period. Took part: how many members posted, commented or reacted.": "Członkowie, którzy najwięcej publikowali i komentowali w tym okresie. Wzięli udział: ilu członków publikowało, komentowało lub reagowało.",
