 "The events of this period: how many members said they are going, and how many tickets were checked in at the door.": "Wydarzenia z tego okresu: ilu członków zapowiedziało udział i ile biletów sprawdzono przy wejściu.",
 "{count, plural, one {# ticket} other {# tickets}} sold, {total} after refunds.": "{count, plural, one {# bilet sprzedany} few {# bilety sprzedane} many {# biletów sprzedanych} other {# biletu sprzedanego}}, {total} po zwrotach.",
