 "No tickets were checked in in this period.": "W tym okresie nie sprawdzono żadnego biletu.",
 "Program progress": "Postępy w programach",
 "Each program: how far the members who started it are on average, how many finished it, and how many started it.": "Każdy program: jak daleko średnio są członkowie, którzy go zaczęli, ilu go ukończyło i ilu zaczęło.",
