 "Improved loading skeleton structures for Explore, Analytics, and Upgrade pages to better match actual page layouts.": "Szkielety ładowania w Odkrywaj, Statystykach i Planach lepiej odpowiadają prawdziwym stronom.",
 "Improved settings page with smoother sticky save bar animations, toast notifications, and faster tab navigation with skeleton loading.": "Ustawienia z płynniejszym paskiem zapisu, powiadomieniami i szybszym przełączaniem kart.",
 "Improvement": "Ulepszenie",
 "In 17TRACK, Settings > Webhook: add this address. 17TRACK signs updates with your API key. Without it Storelib checks every few hours.": "W 17TRACK, Settings > Webhook: dodaj ten adres. 17TRACK podpisuje aktualizacje Twoim kluczem API. Bez tego Storelib sprawdza co kilka godzin.",
