 "In Gelato, Developer › Webhooks, add this address for order status and tracking code updates:": "W Gelato, Developer › Webhooks, dodaj ten adres dla statusu zamówień i numerów śledzenia:",
 "In Google Analytics, Reports › Realtime shows a visit within a minute. The “Data collection isn't active” notice on your stream can take up to 48 hours to go away.": "W Google Analytics Raporty › Czas rzeczywisty pokazują wizytę w ciągu minuty. Komunikat „Zbieranie danych nie jest aktywne” przy strumieniu może zniknąć dopiero po 48 godzinach.",
