 "Member status": "Status członka",
 "Members": "Członkowie",
 "Members are told about announcements.": "Członkowie dostają powiadomienia o ogłoszeniach.",
 "Members can comment on posts here.": "Członkowie mogą tu komentować posty.",
 "Members can read it; nobody can post. Bringing it back makes it a draft.": "Członkowie mogą ją czytać; nikt nie może publikować. Przywrócenie zmienia ją w wersję roboczą.",
 "Members can see who else is here.": "Członkowie widzą, kto jeszcze tu jest.",
 "Members can still read it. Nobody can post or join until you bring it back. Nothing is deleted.": "Członkowie nadal mogą ją czytać. Nikt nie może publikować ani dołączać, dopóki jej nie przywrócisz. Nic nie zostanie usunięte.",
 "Members earn points when their posts and comments get reactions, and climb levels. A leaderboard shows in the community.": "Członkowie zdobywają punkty, gdy ich posty i komentarze dostają reakcje, i awansują na kolejne poziomy. W społeczności widać ranking.",
 "Members get these in their library while their membership lasts.": "Członkowie mają je w bibliotece przez cały okres członkostwa.",
 "Members now": "Członkowie teraz",
 "Members on {name}": "Członkowie: {name}",
 "Members pay for a tier to join.": "Członkowie płacą za poziom, aby dołączyć.",
 "Members pay monthly or yearly to join your community.": "Członkowie płacą miesięcznie lub rocznie, aby dołączyć do społeczności.",
 "Members pay once, in a checkout inside the community. ": "Członkowie płacą raz, w kasie wewnątrz społeczności.",
 "Members pay once, in a checkout inside the community. The meeting link, the address and who else is going open when they have a ticket.": "Członkowie płacą raz, w kasie wewnątrz społeczności. Link do spotkania, adres i lista uczestników pokażą się po zakupie biletu.",
 "Members pay through Stripe. You can add a yearly price or more tiers later.": "Członkowie płacą przez Stripe. Cenę roczną lub kolejne poziomy dodasz później.",
 "Members pay to join, every month, every year or once.": "Członkowie płacą za dołączenie co miesiąc, co rok lub raz.",
 "Members pay you through Stripe. Nobody can join a paid community until payouts are connected.": "Członkowie płacą Ci przez Stripe. Nikt nie dołączy do płatnej społeczności, dopóki nie połączysz wypłat.",
 "Members pay {amount} once, in a checkout inside the community. ": "Członkowie płacą {amount} raz, w kasie wewnątrz społeczności.",
 "Members pay {priceText}.": "Członkowie płacą {priceText}.",
 "Members paying now, including anyone whose card is being retried. Somebody who cancelled keeps access until their period ends and is not counted.": "Członkowie płacący teraz, także ci z ponawianą płatnością kartą. Kto anulował, zachowuje dostęp do końca okresu i nie jest liczony.",
 "Members post": "Publikują członkowie",
 "Members reach levels by taking part. Below it, they see the program with the level it opens at.": "Członkowie zdobywają poziomy, biorąc udział. Poniżej widzą program z poziomem, od którego się otwiera.",
 "Members see it under Learn.": "Członkowie widzą go w Nauce.",
 "Members see posts on their membership page. Put the membership on sale in Settings to let people join.": "Członkowie widzą posty na stronie członkostwa. Wystaw członkostwo na sprzedaż w Ustawieniach, aby ludzie mogli dołączać.",
 "Members see them before they join and when they post.": "Członkowie widzą je przed dołączeniem i przy publikowaniu.",
 "Members stop seeing it here. The course and its buyers are not touched.": "Członkowie przestaną go tu widzieć. Kurs i jego kupujący pozostają bez zmian.",
