 "Off topic": "Nie na temat",
 "Off, buyers pay your prices and nothing more.": "Wyłączone: kupujący płacą Twoje ceny i nic więcej.",
 "Off, each order is made in CJ unpaid, and waits until you pay it there. On, it is confirmed and paid from your CJ balance as soon as your buyer pays.": "Wyłączone: każde zamówienie powstaje w CJ jako nieopłacone i czeka na Twoją płatność. Włączone: jest potwierdzane i opłacane z salda CJ, gdy tylko kupujący zapłaci.",
 "Off, each order waits in {name} as a draft until you approve it there, and {name2} charges you only then. On, it is made and charged as soon as it is paid.": "Wyłączone: każde zamówienie czeka w {name} jako szkic, aż je zatwierdzisz, a {name2} obciąża Cię dopiero wtedy. Włączone: jest tworzone i rozliczane po opłaceniu.",
 "Off, it follows your store setting: {value}{value2}.": "Wyłączone: działa według ustawienia sklepu: {value}{value2}.",
