 "Once it has passed, say": "Po upływie pokaż",
 "Once it is available you can cash it out, and it usually reaches your bank in 1 to 3 business days.": "Gdy środki są dostępne, możesz je wypłacić; zwykle docierają do banku w 1–3 dni robocze.",
 "Once it starts it cannot be taken back. You can stop the ones not yet sent.": "Po rozpoczęciu nie da się tego cofnąć. Możesz zatrzymać te jeszcze niewysłane.",
 "Once per person": "Raz na osobę",
 "Once saved, they'll appear on your OnePage.": "Po zapisaniu pojawią się na OnePage.",
 "Once the items are back, mark them received: you choose whether they go back into stock, and you refund the buyer from the same screen.": "Gdy produkty wrócą, oznacz je jako otrzymane: wybierasz, czy wracają na stan, i zwracasz pieniądze na tym samym ekranie.",
 "One a line, for example\nfree followers\ncrypto signal*": "Po jednym w linii, na przykład\ndarmowi obserwujący\nsygnał krypto*",
 "One email a day at most, listing what sold down to its low stock line.": "Najwyżej jeden e-mail dziennie z listą tego, co spadło do progu.",
 "One email a day per community, so your members keep reading them.": "Jeden e-mail dziennie na społeczność, żeby członkowie dalej je czytali.",
 "One email an hour later with a link back to what they chose, only to buyers who ticked the news box. It stops the moment they buy.": "Jeden e-mail godzinę później z linkiem do wybranych rzeczy, tylko do osób z zaznaczonym newsletterem. Przestaje, gdy kupią.",
 "One email an hour later, only to buyers who ticked the news box. With the news box hidden nobody can tick it, so no reminder goes out.": "Jeden e-mail godzinę później, tylko do osób z zaznaczonym newsletterem. Gdy pole jest ukryte, nikt go nie zaznaczy, więc przypomnienie nie wyjdzie.",
 "One email listing every parcel and its tracking link.": "Jeden e-mail z każdą paczką i jej linkiem do śledzenia.",
