 "One email per order with its tracking link, or saying it's on the way.": "Jeden e-mail na zamówienie z linkiem do śledzenia lub informacją, że jest w drodze.",
 "One event has a price, and nobody can buy a ticket until payouts are connected.": "Jedno wydarzenie ma cenę i nikt nie kupi biletu, dopóki nie połączysz wypłat.",
