 "Only Storelib sees this.": "Widzi to tylko Storelib.",
 "Only YouTube and Vimeo links can be added as a video.": "Jako wideo można dodać tylko linki YouTube i Vimeo.",
 "Only approved translations show, and only once a language is published. Anything not translated yet shows in your default language, never blank.": "Widoczne są tylko zatwierdzone tłumaczenia i tylko po publikacji języka. Nieprzetłumaczone treści są w języku domyślnym, nigdy puste.",
 "Only buyers in {country} can order. You can add more places later.": "Zamawiać mogą tylko kupujący z kraju {country}. Więcej miejsc dodasz później.",
 "Only buyers who asked for your news": "Tylko kupujący, którzy chcą dostawać wiadomości",
