 "The program could not be made. Try again.": "Nie udało się utworzyć programu. Spróbuj ponownie.",
 "The push was large, so Storelib stopped part way. Bring in the rest now.": "Wypchnięcie było duże, więc Storelib przerwał w połowie. Pobierz resztę teraz.",
