 "The same line drives the Low filter in": "Ten sam próg steruje filtrem Niski w",
 "The section could not be written.": "Nie udało się napisać sekcji.",
 "The segment could not be saved. Check your connection and try again.": "Nie udało się zapisać segmentu. Sprawdź połączenie i spróbuj ponownie.",
 "The segment could not be saved. Try again.": "Nie udało się zapisać segmentu. Spróbuj ponownie.",
 "The server takes {time} to answer. Over 0.8 s, every page starts late.": "Serwer odpowiada po {time}. Powyżej 0,8 s każda strona startuje z opóźnieniem.",
 "The sites and apps that sent each visit, by its first page: one line per company, whichever of its addresses or apps the link came through. Visits with no referrer are Direct, under Traffic sources.": "Strony i aplikacje, z których przyszła każda wizyta, według jej pierwszej strony: jeden wiersz na firmę, niezależnie od adresu lub aplikacji linku. Wizyty bez strony odsyłającej są bezpośrednie, w Źródłach ruchu.",
 "The small icon in a browser tab. A square picture, 64 × 64 or larger.": "Mała ikona w karcie przeglądarki. Kwadratowy obraz, 64 × 64 lub większy.",
 "The space could not be saved.": "Nie udało się zapisać przestrzeni.",
 "The stores you help run.": "Sklepy, które pomagasz prowadzić.",
 "The tag loaded but no hit left this browser. An ad blocker or a privacy setting here can stop it: check again with it paused.": "Tag się wczytał, ale z tej przeglądarki nie wyszło żadne trafienie. Może to blokować blokada reklam lub ustawienie prywatności: sprawdź ponownie po jej wstrzymaniu.",
