 "The upload took too long. Try again.": "Przesyłanie trwało za długo. Spróbuj ponownie.",
 "The value is what is saved and counted in Analytics, so keep it short and never change its meaning. The label is the words people see.": "Wartość jest zapisywana i liczona w Analityce, więc niech będzie krótka i nie zmieniaj jej znaczenia. Etykieta to tekst widoczny dla ludzi.",
 "The verified badge and hiding Storelib branding are part of Pro. Upgrade to save these changes.": "Odznaka weryfikacji i ukrycie marki Storelib są w planie Pro. Przejdź na Pro, aby zapisać te zmiany.",
