 "This community is archived. Bring it back to change it.": "Ta społeczność jest zarchiwizowana. Przywróć ją, aby ją zmienić.",
 "This community is archived. Members can read it, nobody can post. Bring it back from Settings.": "Ta społeczność jest zarchiwizowana. Członkowie mogą czytać, nikt nie może publikować. Przywróć ją w Ustawieniach.",
 "This course's modules and lessons are edited in the course itself, and change here too.": "Moduły i lekcje tego kursu edytuje się w samym kursie; zmiany widać też tutaj.",
