 "This gradient was written by hand in a form this control cannot read. It is kept as it is; changing anything below replaces it.": "Ten gradient wpisano ręcznie w formie, której ta kontrolka nie odczyta. Zostaje bez zmian; zmiana poniżej go zastąpi.",
 "This is not a link to a video file. It should end in .mp4, .webm or .mov.": "To nie jest link do pliku wideo. Powinien kończyć się na .mp4, .webm lub .mov.",
 "This is not one of your communities, so the section shows nothing.": "To nie Twoja społeczność, więc sekcja nic nie pokazuje.",
