 "This one stays on the list: a reason that isn't on it is kept as this.": "Ten zostaje na liście: powód spoza listy zapisuje się jako ten.",
 "This order has no receipt to send": "To zamówienie nie ma potwierdzenia do wysłania",
 "This order was cancelled and its stock released. It was to be paid in cash on delivery, so there is nothing to refund.": "To zamówienie zostało anulowane, a jego zapas zwolniony. Miało być opłacone przy odbiorze, więc nie ma czego zwracać.",
 "This order was cancelled and its stock released. Refund the payment with Refund if you haven't.": "To zamówienie anulowano, a towar zwolniono. Zwróć płatność przyciskiem Zwrot, jeśli jeszcze tego nie zrobiono.",
