 "This period has more activity than one report reads at once. Choose a shorter period for exact figures.": "W tym okresie jest więcej aktywności, niż raport odczyta naraz. Wybierz krótszy okres, aby zobaczyć dokładne liczby.",
 "This period has more reviews than one chart reads. Pick a shorter period for exact numbers.": "Ten okres ma więcej opinii, niż wykres odczytuje. Wybierz krótszy okres, aby zobaczyć dokładne liczby.",
