 "This program is sold on its own. Buy it once and it stays in your Learn for as long as you are a member.": "Ten program jest sprzedawany osobno. Kup go raz, a zostanie w Twojej Nauce, dopóki jesteś członkiem.",
 "This program opens at {value}. Levels come from taking part in the community.": "Ten program otwiera się na: {value}. Poziomy zdobywa się, biorąc udział w społeczności.",
 "This publish will not be backed up. Run supabase/sql/RUN_THEME_BACKUPS.sql once to turn backups on.": "Ta publikacja nie będzie mieć kopii zapasowej. Uruchom raz supabase/sql/RUN_THEME_BACKUPS.sql, aby włączyć kopie.",
 "This records the cash you gave back. Nothing is sent to a card, and the buyer gets an email about it.": "To zapisuje gotówkę, którą oddałeś. Nic nie trafia na kartę, a kupujący dostaje o tym e-mail.",
 "This replaces {domain}. For 30 days {domain2} sends its visitors on to {clean}, then it stops. Press Replace to go ahead.": "To zastępuje {domain}. Przez 30 dni {domain2} przekierowuje na {clean}, potem przestaje. Naciśnij Zastąp, aby kontynuować.",
 "This review is already on your store.": "Ta opinia jest już w Twoim sklepie.",
 "This sale cannot be refunded.": "Tej sprzedaży nie można zwrócić.",
 "This section shows {max} at most. Remove one to add another.": "Ta sekcja pokazuje maksymalnie {max}. Usuń jedną, aby dodać inną.",
 "This setting takes a {what}.": "To ustawienie przyjmuje: {what}.",
