 "This will appear below your name on your page": "Pojawi się pod Twoim imieniem na stronie",
 "This will disable new paid checkouts until you reconnect. Historical orders will remain intact.": "Nowe płatne zamówienia będą wyłączone do ponownego połączenia. Dotychczasowe zamówienia pozostaną bez zmian.",
