 "Visitors": "Odwiedzający",
 "Visitors are matched by the country they browse from, and can change it with the currency or country selector. Their choice is remembered.": "Odwiedzający są przypisywani według kraju, z którego przeglądają, i mogą to zmienić przełącznikiem waluty lub kraju. Wybór jest zapamiętywany.",
 "Visitors are matched by the country they browse from, and can change it with the currency selector. Their choice is remembered.": "Odwiedzający są przypisywani według kraju, z którego przeglądają, i mogą to zmienić selektorem waluty. Ich wybór jest zapamiętywany.",
 "Visitors by the system of their device, with its share of all visitors. Read from the browser's signature, and from its platform hint where the signature is vague.": "Odwiedzający według systemu urządzenia, z udziałem we wszystkich. Odczytane z sygnatury przeglądarki, a z podpowiedzi platformy, gdy sygnatura jest niejasna.",
 "Visitors confirm before it opens": "Odwiedzający potwierdzają przed otwarciem",
 "Visitors go to {goesTo} for 30 days, then it stops.": "Odwiedzający trafiają na {goesTo} przez 30 dni, potem to się kończy.",
 "Visitors in the EU, the UK and Switzerland are counted in full once they accept cookies; before that Google gets a cookieless ping.": "Odwiedzający z UE, Wielkiej Brytanii i Szwajcarii są liczeni w pełni po zaakceptowaniu plików cookie; wcześniej Google dostaje ping bez cookie.",
 "Visitors may see a different order depending on their location or preferences.": "Odwiedzający mogą widzieć inną kolejność zależnie od lokalizacji lub preferencji.",
 "Visitors open your website in your default language and store currency, and switch with your theme's own selectors.": "Odwiedzający otwierają Twoją stronę w domyślnym języku i walucie sklepu, a zmieniają je selektorami motywu.",
 "Visitors see a placeholder until you publish again.": "Odwiedzający zobaczą stronę zastępczą, dopóki nie opublikujesz ponownie.",
 "Visitors see a placeholder. {name} was the last one live.": "Odwiedzający widzą stronę zastępczą. Ostatnio opublikowana była {name}.",
 "Visitors see it once {title} is published in Products › Collections.": "Odwiedzający zobaczą ją po opublikowaniu {title} w Produkty › Kolekcje.",
 "Visitors see the last version you published.": "Odwiedzający widzą ostatnio opublikowaną wersję.",
 "Visitors see this once {name} is published and public.": "Odwiedzający zobaczą to, gdy {name} będzie opublikowana i publiczna.",
 "Visitors see your password page until they type the password.": "Odwiedzający widzą stronę hasła, dopóki go nie wpiszą.",
 "Visitors start in": "Odwiedzający zaczynają w języku",
 "Visitors switch with the language selector. On a Storelib theme it sits under the footer by itself. On a theme you imported from Shopify it is the theme's own selector, turned on in the editor (Show language, usually in the header or footer).": "Odwiedzający zmieniają język przełącznikiem. W motywie Storelib jest sam pod stopką. W motywie zaimportowanym z Shopify to przełącznik motywu, włączany w edytorze (Show language, zwykle w nagłówku lub stopce).",
 "Visitors switch with your theme's language selector. Turn on Show visitors their own language to open a first visit in their browser's language.": "Odwiedzający przełączają selektorem języka Twojego motywu. Włącz Pokazuj odwiedzającym ich język, by pierwsza wizyta otwierała się w języku przeglądarki.",
 "Visitors: where visits came from, from their connection. Orders: where buyers are, from the order, with their revenue.": "Odwiedzający: skąd przyszły wizyty, według połączenia. Zamówienia: gdzie są kupujący, według zamówienia, z przychodem.",
 "Visits to your pages, by day.": "Wizyty na Twoich stronach, dziennie.",
