 "What you price in. Visitors in {country}, and anywhere not listed under More currencies, see prices in it and pay in it.": "Waluta Twoich cen. Odwiedzający z kraju {country} i z każdego miejsca spoza listy Więcej walut widzą w niej ceny i w niej płacą.",
 "What you will cover and who it is for": "Co omówisz i dla kogo to jest",
 "What you wrote in this email is replaced.": "To, co napisano w tym e-mailu, zostanie zastąpione.",
 "What your buyers and members get from you, and when: digital products, physical products and communities, each apart. Open one to see it as it is sent and change its words. A reply comes to your contact email.": "Co Twoi kupujący i członkowie dostają od Ciebie, i kiedy: produkty cyfrowe, produkty fizyczne i społeczności, każde osobno. Otwórz e-mail, aby zobaczyć go tak, jak jest wysyłany, i zmienić jego słowa. Odpowiedź trafia na Twój e-mail kontaktowy.",
 "What your buyers get from you, and when. Open one to see it and change its words. Each goes out with your store's name, and a reply comes to your contact email.": "Co i kiedy otrzymują od Ciebie kupujący. Otwórz wiadomość, aby ją zobaczyć i zmienić treść. Każda wychodzi z nazwą sklepu, a odpowiedzi trafiają na Twój e-mail kontaktowy.",
 "What your completed sales took in over this period, before fees and refunds.": "Wpływy z zakończonej sprzedaży w tym okresie, przed opłatami i zwrotami.",
 "What your website is written in now. It keeps its addresses as they are.": "W jakim języku jest teraz napisana strona. Adresy pozostają bez zmian.",
 "What's Included": "Co zawiera",
 "What's included in this variant...": "Co zawiera ten wariant...",
