 "WhatsApp Group URL": "URL grupy WhatsApp",
 "Wheel throwing, from clay to cup": "Toczenie na kole, od gliny do kubka",
 "When": "Kiedy",
 "When a buyer asks to return items, so they know it arrived.": "Gdy kupujący poprosi o zwrot, aby wiedział, że prośba dotarła.",
 "When a buyer has a problem with an order (it hasn't arrived, it came damaged, they want a refund), they ask from their order page and it lands here and in your email. You answer first; either of you can ask Storelib to step in.": "Gdy kupujący ma problem z zamówieniem (nie dotarło, przyszło uszkodzone, chce zwrotu), zgłasza to ze strony zamówienia, a sprawa trafia tutaj i na Twój e-mail. Odpowiadasz pierwszy; każde z was może poprosić Storelib o pomoc.",
 "When a course opens in the classroom": "Gdy w klasie otwiera się kurs",
 "When a draft was last changed.": "Kiedy szkic był ostatnio zmieniany.",
 "When a review comes in": "Gdy pojawi się opinia",
 "When a shipment is marked as failed: the carrier, or your own delivery, couldn't deliver it.": "Gdy wysyłka zostanie oznaczona jako nieudana: przewoźnik lub Twoja dostawa nie zdołała jej doręczyć.",
 "When a store's owner invites you, it shows here and you can open it from your own account.": "Gdy właściciel sklepu Cię zaprosi, sklep pojawi się tutaj i otworzysz go ze swojego konta.",
 "When a ticket is refunded.": "Gdy bilet zostaje zwrócony.",
 "When buyers can come. Shown at checkout and in the pickup email.": "Kiedy kupujący mogą przyjść. Widoczne w kasie i w e-mailu o odbiorze.",
 "When does Pro pay for itself?": "Kiedy Pro się zwraca?",
 "When it pushes to": "Gdy wypchnie do",
