 "Your prices are in {baseCurrency}. Cards are charged in {chargeCurrency}. A market in another currency shows an estimate converted at the European Central Bank's rate, and says so before payment.": "Twoje ceny są w {baseCurrency}. Karty są obciążane w {chargeCurrency}. Rynek w innej walucie pokazuje szacunek po kursie Europejskiego Banku Centralnego i informuje o tym przed płatnością.",
