 "Your product has no stock yet. Add some so buyers can order it.": "Produkt nie ma jeszcze stanu. Dodaj towar, aby kupujący mogli zamawiać.",
 "Your products": "Twoje produkty",
 "Your products, pages, customers and orders stay as they are.": "Produkty, strony, klienci i zamówienia pozostaną bez zmian.",
 "Your products, pages, customers and orders stay exactly as they are. The Free fee applies to new sales, and the things only Pro has, like your own domain and hidden branding, stop at the end of your paid period.": "Produkty, strony, klienci i zamówienia zostają bez zmian. Do nowej sprzedaży stosuje się prowizję Free, a funkcje tylko z Pro, jak własna domena i ukryta marka, wyłączą się z końcem opłaconego okresu.",
 "Your profile photo, until you choose a logo.": "Twoje zdjęcie profilowe, dopóki nie wybierzesz logo.",
